-- E-Learning Hub Database Schema and Seed Data
-- Import this SQL file into your local phpMyAdmin (MySQL) to seed your database!

SET SQL_MODE = "NO_AUTO_VALUE_ON_ZERO";
START TRANSACTION;
SET time_zone = "+00:00";

-- --------------------------------------------------------
-- Table structure for table `users`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `users` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `username` VARCHAR(50) NOT NULL UNIQUE,
  `email` VARCHAR(100) NOT NULL UNIQUE,
  `password` VARCHAR(255) NOT NULL,
  `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- --------------------------------------------------------
-- Table structure for table `courses`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `courses` (
  `id` VARCHAR(50) NOT NULL PRIMARY KEY,
  `title` VARCHAR(150) NOT NULL,
  `category` VARCHAR(100) NOT NULL,
  `level` ENUM('Beginner', 'Intermediate', 'Advanced') NOT NULL,
  `duration` VARCHAR(50) NOT NULL,
  `instructor` VARCHAR(100) NOT NULL,
  `rating` DECIMAL(3,2) NOT NULL,
  `students_enrolled` INT NOT NULL,
  `description` TEXT NOT NULL,
  `image` VARCHAR(255) NOT NULL,
  `video_url` VARCHAR(255) NOT NULL,
  `overview` TEXT NOT NULL,
  `objectives` TEXT NOT NULL, -- Stored as semi-colon separated lists
  `code_example` TEXT
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- --------------------------------------------------------
-- Table structure for table `registrations`
-- --------------------------------------------------------

CREATE TABLE IF NOT EXISTS `registrations` (
  `id` INT AUTO_INCREMENT PRIMARY KEY,
  `user_id` INT NOT NULL,
  `course_id` VARCHAR(50) NOT NULL,
  `registration_date` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
  FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON DELETE CASCADE,
  FOREIGN KEY (`course_id`) REFERENCES `courses`(`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- --------------------------------------------------------
-- Seeding All 16 Course Specifications
-- --------------------------------------------------------

INSERT INTO `courses` (`id`, `title`, `category`, `level`, `duration`, `instructor`, `rating`, `students_enrolled`, `description`, `image`, `video_url`, `overview`, `objectives`, `code_example`) VALUES
('html-css', 'HTML5 & CSS3 Masterclass', 'Web Development', 'Beginner', '6 Weeks', 'Dr. Govindharajan', 4.80, 1250, 'Learn the absolute foundations of web development. Build responsive, pixel-perfect layouts using HTML5, CSS3, Flexbox, Grid, and beautiful transitions.', 'https://images.unsplash.com/photo-1507238691740-187a5b1d37b8?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/Dp3qSIn74-Y', 'This course is designed for absolute beginners who want to step into the world of web engineering. You will learn the semantic structures of HTML5, how to style websites beautifully using modern CSS3, and how to create mobile-first responsive interfaces.', 'Master HTML5 semantic elements and document layouts;Understand CSS Box Model, Flexbox, Grid, and Custom Properties;Implement fluid responsive design using Media Queries;Build a multi-page portfolio website from scratch', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <title>Cool Layout</title>\n  <style>\n    .grid-container {\n      display: grid;\n      grid-template-columns: repeat(auto-fit, minmax(250px, 1fr));\n      gap: 20px;\n      padding: 20px;\n    }\n    .card {\n      background: white;\n      border-radius: 8px;\n      box-shadow: 0 4px 6px rgba(0,0,0,0.1);\n      padding: 15px;\n      transition: transform 0.2s;\n    }\n    .card:hover { transform: translateY(-5px); }\n  </style>\n</head>\n<body>\n  <main class=\"grid-container\">\n    <div class=\"card\"><h3>Feature One</h3><p>Semantic HTML & CSS Layouts</p></div>\n  </main>\n</body>\n</html>'),

('javascript', 'Modern JavaScript (ES6+)', 'Web Development', 'Beginner', '8 Weeks', 'Sara Johnson', 4.90, 1850, 'Go from scratch to mastering JavaScript. Understand variables, DOM manipulation, asynchronous programming, and fetch web APIs.', 'https://images.unsplash.com/photo-1579468118864-1b9ea3c0db4a?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/W6NZfCO5SIk', 'JavaScript is the engine of the modern web. In this comprehensive course, you will grasp core computer science structures in JS and shift into web interactivity, event-driven development, and modular architecture.', 'Develop algorithmic thinking using conditions, loops, and objects;Manipulate the Document Object Model (DOM) to build interactive components;Implement asynchronous patterns with Promises and Async/Await;Manage application state client-side safely', 'const fetchUserData = async (userId) => {\n  try {\n    const response = await fetch(\"https://api.example.com/users/42\");\n    const data = await response.json();\n    console.log(data);\n  } catch (err) {\n    console.error(err);\n  }\n};'),

('responsive-design', 'Responsive Web Design Essentials', 'Design', 'Intermediate', '4 Weeks', 'David Miller', 4.70, 980, 'Design websites that look incredible on everything from a massive desktop screen down to mobile displays. Learn advanced fluid design concepts.', 'https://images.unsplash.com/photo-1551288049-bebda4e38f71?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/srvUrASo084', 'Responsive design is no longer an option—it is a critical requirement. This course teaches fluid grid patterns, typography resizing, adaptive image serving, and cross-browser responsiveness techniques.', 'Adopt a strict mobile-first design strategy;Apply fluid typography rules using clamp(), vh, vw, and rem;Deploy CSS Grid container autofills and custom breakpoints;Optimize vector and raster media for fast page loads', '.container {\n  width: 100%;\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 1.5rem;\n}'),

('php-beginners', 'PHP Backend Development for Beginners', 'Web Development', 'Beginner', '8 Weeks', 'Prof. Govindharajan', 4.80, 1540, 'Unlock server-side scripting! Understand PHP fundamentals, request routing, session management, security checks, and form processing.', 'https://images.unsplash.com/photo-1599507593499-a3f7f7d9a22a?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/2eebptXfEvw', 'PHP powers over 75% of the web. This beginner-friendly course teaches backend variables, condition paths, superglobals, stateful user sessions, password hashing, and dynamic server-side page generation.', 'Configure PHP environments and execute basic server-side scripts;Securely process forms with GET, POST, and filter inputs;Establish secure user login sessions;Handle file uploads and process remote API data payloads', '<?php\nsession_start();\n$username = filter_input(INPUT_POST, \"username\", FILTER_SANITIZE_SPECIAL_CHARS);\necho \"Hello, \" . $username;\n?>'),

('mysql-db', 'MySQL Relational Databases & SQL', 'Database', 'Beginner', '6 Weeks', 'Alan Parker', 4.70, 1110, 'Design relational database schemas. Master SQL commands, write JOINs, index columns for performance, and run complex secure database queries.', 'https://images.unsplash.com/photo-1544383835-bda2bc66a55d?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/HXV3zeQKqGY', 'Any robust web application needs a solid database. This course takes you into SQL (Structured Query Language), database normalizations, primary/foreign keys, joins, index optimizations, and prepared queries.', 'Design schema blueprints with logical normalizations;Perform secure inserts, updates, deletes, and complex reads;Utilize inner, left, and outer joins to read across multiple tables;Write prepared statements to prevent SQL Injection attacks', 'CREATE TABLE users (\n    id INT AUTO_INCREMENT PRIMARY KEY,\n    username VARCHAR(50) NOT NULL UNIQUE\n);'),

('react-essentials', 'React.js Component Architecture', 'Web Development', 'Intermediate', '8 Weeks', 'Emily Chen', 4.90, 2200, 'Build modern dynamic user interfaces. Learn state managers, hooks, routing, custom hooks, and context APIs.', 'https://images.unsplash.com/photo-1633356122544-f134324a6cee?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/Ke90Tje7VS0', 'React is the standard library for modern single-page applications. This course takes you on a complete hands-on path from virtual DOM rendering up to complex custom hooks, global context engines, and responsive micro-animations.', 'Master declarative component writing and props workflows;Synthesize reactivity with useState, useEffect, and useRef;Build performant elements by avoiding redundant re-renders;Manage global state cleanly via the React Context API', 'import React, { useState } from \"react\";\nexport default function Toggle() {\n  const [on, setOn] = useState(false);\n  return <button onClick={() => setOn(!on)}>{on ? \"ON\" : \"OFF\"}</button>;\n}'),

('python-bootcamp', 'Python Programming Bootcamp', 'Software Engineering', 'Beginner', '8 Weeks', 'Mark Vance', 4.90, 2100, 'Start your coding journey with Python. Learn loops, logic paths, object-oriented principles, file structures, and data science foundations.', 'https://images.unsplash.com/photo-1526374965328-7f61d4dc18c5?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/_uQrJ0TkZlc', 'Python simple syntax and powerful versatility make it a leading programming language. In this bootcamp, you will go from elementary control logic up to complex list comprehensions, object systems, and file analyzers.', 'Write clear, readable, and pythonic code;Leverage loops, lists, sets, and dictionaries to process large datasets;Implement file handling and custom exception structures;Apply Object-Oriented Programming (OOP) classes and inheritances', 'class FileStats:\n    def __init__(self, filepath):\n        self.filepath = filepath'),

('node-express', 'Scalable Node.js & Express REST APIs', 'Web Development', 'Intermediate', '6 Weeks', 'Leo Carter', 4.80, 1420, 'Build robust, rapid backends. Write REST APIs with Node and Express, configure middlewares, handle authentication, and hook up databases.', 'https://images.unsplash.com/photo-1555066931-4365d14bab8c?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/Oe421EPjeBE', 'JavaScript on the server is incredibly powerful. You will build high-concurrency routing engines, handle secure JWT token auth, integrate database calls, and format clean JSON payloads for client apps.', 'Construct server routers with dynamic path params and queries;Configure core middle-tier plugins for logging, CORS, and body parsing;Enforce access controls using JWT token verifications;Perform database read/write actions within route closures', 'const express = require(\"express\");\nconst app = express();\napp.listen(3000);'),

('ui-ux', 'UI/UX Design Principles & Figma', 'Design', 'Beginner', '5 Weeks', 'Rachel Moore', 4.80, 1150, 'Design mockups and prototypes. Master typography scales, structural layout spacing, color matching, and building interactive designs in Figma.', 'https://images.unsplash.com/photo-1561070791-26c113006238?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/FTFaQW1ZWY4', 'A great app starts with brilliant design. You will study layout rhythms, high-contrast typography, interactive system feedbacks, and wireframe prototypes using Figma.', 'Create cohesive visual mood boards and contrast color themes;Apply hierarchical typography styles to direct reading flows;Draft functional wireframes and clickable UI prototypes;Design responsive user interfaces adapted for multiple viewports', ':root {\n  --font-body: \"Inter\", sans-serif;\n  --space-4: 1rem;\n}'),

('dsa-core', 'Data Structures & Algorithms in JS', 'Software Engineering', 'Advanced', '10 Weeks', 'Dr. Alice Robert', 4.90, 890, 'Ace your coding interviews! Understand Arrays, Linked Lists, Stacks, Queues, Hash Tables, Trees, Graphs, Sorting algorithms, and Big-O notation.', 'https://images.unsplash.com/photo-1605379399642-870262d3d051?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/8hly31xKli0', 'Data structures and algorithms are the bedrock of computer science. This advanced course teaches memory management, runtime efficiency evaluation (Big O), tree transversals, graphs, and search/sort paths.', 'Calculate runtime complexities (Big O) of custom algorithms;Implement core structures manually;Perform graph searches using Breadth-First and Depth-First transversals;Write highly optimal solutions for algorithmic challenges', 'class TreeNode {\n  constructor(value) {\n    this.value = value;\n    this.left = null;\n    this.right = null;\n  }\n}'),

('cyber-sec', 'Cyber Security & Secure Web Coding', 'Software Engineering', 'Intermediate', '6 Weeks', 'Nikhil Raj', 4.80, 1040, 'Learn how to defend web apps from hackers. Prevent SQL injection, XSS, CSRF attacks, configure secure HTTPS headers, and manage sessions safely.', 'https://images.unsplash.com/photo-1550751827-4bd374c3f58b?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/6scgP6-m684', 'Writing code that works is not enough; your code must be resilient against exploits. In this course, you will study security structures, session hijacking mitigations, cryptographic salting, and secure communication.', 'Audit and eliminate SQL Injection vulnerabilities completely;Deploy Content Security Policies (CSP) to stop XSS scripts;Incorporate anti-CSRF token verification on state-changing requests;Implement robust cryptographic standard hashing for all passwords', 'const helmet = require(\"helmet\");\napp.use(helmet());'),

('cloud-computing', 'Cloud Computing Fundamentals (AWS & GCP)', 'Software Engineering', 'Intermediate', '7 Weeks', 'George Lopez', 4.70, 1120, 'Take your apps to the skies. Learn cloud basics, virtual servers, serverless, storage buckets, and deployment automation.', 'https://images.unsplash.com/photo-1451187580459-43490279c0fa?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/2Idv0e88K4I', 'Transition from local hosting to highly resilient, global cloud architectures. This course covers cloud service models, networking setups, security access matrices, and container hosting.', 'Differentiate and select between AWS, GCP, and Azure options;Deploy scalable server instances and route traffic using load balancers;Configure object buckets for highly accessible asset delivery;Draft Identity and Access Management (IAM) security policies', 'Resources:\n  SecureBucket:\n    Type: AWS::S3::Bucket'),

('git-github', 'Git & GitHub Version Control', 'Software Engineering', 'Beginner', '3 Weeks', 'Clara Oswald', 4.80, 1590, 'Collaborate like a pro. Learn git commits, branching, merging, resolving conflicts, pull requests, and setting up collaborative project boards.', 'https://images.unsplash.com/photo-1618401471353-b98aedd07871?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/RGOj5yH7evk', 'Version control is the lifeblood of software collaboration. This course guides you step-by-step from locally tracking files to raising structured Pull Requests (PRs), reviewing team updates, and rolling back changes.', 'Initialize repositories and manage files using Git commands;Handle standard branch merges and isolate conflicts;Raise, discuss, and resolve remote Pull Requests on GitHub;Utilize Git stash, rebase, and cherry-pick for cleaner histories', 'git checkout -b feature/elearning-courses\ngit commit -m \"add data\"'),

('machine-learning', 'Introduction to Machine Learning', 'Software Engineering', 'Advanced', '10 Weeks', 'Dr. Victor Stone', 4.90, 920, 'Start your artificial intelligence journey. Understand regression, classification, clustering, neural networks, and how to train models in Python.', 'https://images.unsplash.com/photo-1527474305487-b87b222841cc?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/GwIo3gDZUtQ', 'Machine Learning is transforming industries. This comprehensive, advanced course provides high-fidelity explanations of ML theory, model optimization, feature engineering, and neural architectures.', 'Clean, normalize, and split data collections for training;Build and optimize Linear Regression and Decision Tree models;Train neural classifiers with scikit-learn and TensorFlow;Evaluate model performance metrics', 'from sklearn.ensemble import RandomForestClassifier\nmodel = RandomForestClassifier()'),

('devops-cicd', 'DevOps & Automating CI/CD Pipelines', 'Software Engineering', 'Advanced', '8 Weeks', 'Marcus Aurelius', 4.80, 810, 'Learn how modern software teams build and deploy code continuously. Master Docker, GitHub Actions, and container deployment flows.', 'https://images.unsplash.com/photo-1618401471353-b98aedd07871?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/RGOj5yH7evk', 'Continuous Integration and Continuous Deployment (CI/CD) ensures software is tested and shipped reliably. This advanced course teaches containerization with Docker, YAML workflows, and cloud container hosting.', 'Write Dockerfiles to pack and isolate web applications;Draft YAML config scripts for automatic tests on push;Implement secure rolling cloud updates with zero downtime;Set up monitoring alerts to capture runtime container crashes', 'FROM node:20-alpine AS builder\nWORKDIR /app\nRUN npm run build'),

('digital-marketing', 'Digital Marketing Secrets & SEO', 'Design', 'Beginner', '5 Weeks', 'Sarah Jenkins', 4.70, 1280, 'Drive traffic and rank high. Learn search engine optimization, Google Analytics, social media algorithms, and content strategies.', 'https://images.unsplash.com/photo-1460925895917-afdab827c52f?auto=format&fit=crop&w=600&q=80', 'https://www.youtube.com/embed/nU-IIXDE39U', 'Building a great app is only half the battle; people must find it. This course covers keywords search, semantic meta tags, off-page link structures, campaign setup, and visitor tracking frameworks.', 'Optimize search visibility using semantic markup and high-value keywords;Configure custom Google Tag Manager and Analytics events;Establish email marketing automations that nurture sales leads;Analyze traffic acquisition patterns to optimize conversion rates', '<meta name=\"description\" content=\"Master web development with expert courses.\">');

